'use strict';

// The web control surface: the same /api/v1 routes the headset speaks.
// Plain DOM, textContent only, so agent output never becomes markup.

// Every route the page calls; `{id}` is filled by `route`. A test reads
// this table to check the host answers each one.
const API = {
  info: '/api/v1/info',
  pair: '/api/v1/pair',
  me: '/api/v1/me',
  projects: '/api/v1/projects',
  sessions: '/api/v1/projects/{id}/sessions',
  waiting: '/api/v1/waiting',
  lastResponse: '/api/v1/sessions/{id}/last-response',
  screen: '/api/v1/sessions/{id}/screen',
  send: '/api/v1/sessions/{id}/send',
  events: '/api/v1/events',
};

const STORE_KEY = 'switchboard-host';
const POLL_FAST = 3000;
const POLL_SLOW = 20000;
const RETRY_FIRST = 5000;
const RETRY_MAX = 60000;

// --- pure parts

function route(template, id) {
  return template.replace('{id}', encodeURIComponent(id));
}

// `#code=..&key=..&id=..` -> the three values, or null if one is missing.
function parseFragment(hash) {
  const params = new URLSearchParams(hash.replace(/^#/, ''));
  const code = params.get('code');
  const key = params.get('key');
  const id = params.get('id');
  return code && key && id ? { code, key, id } : null;
}

function deviceName(ua, touchPoints) {
  const browser = /Edg\//.test(ua)
    ? 'Edge'
    : /Chrome\/|CriOS/.test(ua)
      ? 'Chrome'
      : /Firefox\/|FxiOS/.test(ua)
        ? 'Firefox'
        : /Safari\//.test(ua)
          ? 'Safari'
          : null;
  let device = null;
  if (/iPhone/.test(ua)) device = 'iPhone';
  else if (/iPad/.test(ua) || (/Macintosh/.test(ua) && touchPoints > 1)) device = 'iPad';
  else if (/Android/.test(ua)) device = 'Android';
  else if (/Macintosh|Mac OS X/.test(ua)) device = 'Mac';
  else if (/Windows/.test(ua)) device = 'Windows';
  else if (/Linux/.test(ua)) device = 'Linux';
  return browser && device ? `${browser} on ${device}` : 'Browser';
}

// What a 401 means, from what /info says now against what this page
// stored at pairing. The host cannot say "revoked": a removed device and
// an unknown token answer the same.
function infer401(stored, info) {
  if (!stored) return 'unpaired';
  if (!info) return 'unreachable';
  return info.server_id === stored.server_id && info.spki_sha256 === stored.spki_sha256
    ? 'removed'
    : 'changed';
}

// Whether a reply is newer than what is applied: a new epoch always is,
// the same epoch needs a revision no lower.
function isCurrent(applied, reply) {
  if (!applied || applied.epoch !== reply.epoch) return true;
  return reply.revision >= applied.revision;
}

function randomHex(bytes) {
  const raw = new Uint8Array(bytes);
  crypto.getRandomValues(raw);
  return Array.from(raw, (b) => b.toString(16).padStart(2, '0')).join('');
}

function ago(ms, now) {
  if (!ms) return '';
  const s = Math.max(0, Math.round((now - ms) / 1000));
  if (s < 60) return `${s}s ago`;
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
  return `${Math.floor(s / 86400)}d ago`;
}

// Projects with a waiting session first, waiting sessions first inside.
function arrange(groups) {
  const waits = (g) => g.sessions.some((s) => s.waiting);
  groups.forEach((g) => g.sessions.sort((a, b) => Number(b.waiting) - Number(a.waiting)));
  return groups.slice().sort((a, b) => Number(waits(b)) - Number(waits(a)));
}

// --- the page

const page = {
  stored: null,
  me: null,
  groups: [],
  marker: null,
  applied: null,
  contentApplied: {},
  open: null,
  pending: {},
  pollTimer: null,
  pollMs: POLL_FAST,
  socket: null,
  retryMs: RETRY_FIRST,
  retryTimer: null,
  refreshing: false,
};

function el(tag, text, className) {
  const node = document.createElement(tag);
  if (text !== undefined && text !== null) node.textContent = text;
  if (className) node.className = className;
  return node;
}

function show(...nodes) {
  document.getElementById('app').replaceChildren(...nodes);
}

function message(title, text, ...extra) {
  show(el('h2', title), el('p', text), ...extra);
}

function loadStored() {
  try {
    return JSON.parse(localStorage.getItem(STORE_KEY));
  } catch {
    return null;
  }
}

function saveStored(value) {
  localStorage.setItem(STORE_KEY, JSON.stringify(value));
}

async function call(path, options) {
  const response = await fetch(path, { credentials: 'same-origin', ...options });
  let body = null;
  try {
    body = await response.json();
  } catch {
    body = null;
  }
  return { status: response.status, body };
}

async function readInfo() {
  try {
    const r = await call(API.info);
    return r.status === 200 ? r.body.body : null;
  } catch {
    return null;
  }
}

function stopLoops() {
  clearInterval(page.pollTimer);
  clearTimeout(page.retryTimer);
  page.pollTimer = null;
  if (page.socket) {
    page.socket.onclose = null;
    page.socket.close();
    page.socket = null;
  }
}

async function unauthorized() {
  stopLoops();
  document.getElementById('bar').hidden = true;
  const verdict = infer401(page.stored, await readInfo());
  const again = 'Open the pairing window on the Mac and scan its code.';
  if (verdict === 'removed') {
    message('Removed', `This device was removed on the host. ${again}`);
  } else if (verdict === 'changed') {
    message('Identity changed', `The host's identity changed. ${again}`);
  } else if (verdict === 'unreachable') {
    message('Cannot reach the host', 'Check that the Mac is awake and on the same network.');
  } else {
    message('Not paired', again);
  }
}

// --- pairing and boot

const PAIR_ERRORS = {
  pairing_closed: 'Pairing is not open on the Mac. Open the pairing window and scan again.',
  wrong_code: 'The code did not match. Scan the code again.',
  wrong_key: 'This is not the Mac whose code was scanned.',
  rate_limited: 'Too many tries. Wait a minute.',
};

async function pairFrom(invite) {
  message('Pairing', 'Checking the host…');
  const info = await readInfo();
  if (!info) {
    message('Cannot reach the host', 'Check that the Mac is awake and on the same network.');
    return;
  }
  if (info.spki_sha256 !== invite.key || info.server_id !== invite.id) {
    message(
      'Different Switchboard',
      'This address is a different Switchboard than the code was for. Nothing was sent.',
    );
    return;
  }
  const r = await call(API.pair, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      code: invite.code,
      spki_sha256: invite.key,
      device_name: deviceName(navigator.userAgent, navigator.maxTouchPoints),
      transport: 'cookie',
    }),
  });
  if (r.status !== 200) {
    const code = r.body && r.body.error && r.body.error.code;
    message('Not paired', PAIR_ERRORS[code] || 'Pairing failed.');
    return;
  }
  page.stored = {
    server_id: info.server_id,
    spki_sha256: info.spki_sha256,
    server_name: info.server_name,
  };
  saveStored(page.stored);
  await start();
}

async function boot() {
  page.stored = loadStored();
  const invite = parseFragment(location.hash);
  if (invite) {
    // Before anything else: the code is single use, but it should not
    // stay in the address bar.
    history.replaceState(null, '', location.pathname);
    await pairFrom(invite);
    return;
  }
  await start();
}

async function start() {
  let r;
  try {
    r = await call(API.me);
  } catch {
    message('Cannot reach the host', 'Check that the Mac is awake and on the same network.');
    return;
  }
  if (r.status === 401) {
    await unauthorized();
    return;
  }
  if (r.status !== 200) {
    message('Error', 'The host did not answer as expected.');
    return;
  }
  page.me = r.body.body;
  document.getElementById('host-name').textContent = page.me.server_name;
  document.getElementById('scope').textContent = `${page.me.scope} access`;
  document.getElementById('bar').hidden = false;
  await refresh();
  startPolling(POLL_FAST);
  connectSocket();
}

// --- reading

async function refresh() {
  if (page.refreshing) return;
  page.refreshing = true;
  try {
    const waiting = await call(API.waiting);
    if (waiting.status === 401) return await unauthorized();
    if (waiting.status !== 200) return;
    const marker = `${waiting.body.epoch}:${waiting.body.revision}`;
    if (!isCurrent(page.applied, waiting.body)) return;
    const projects = await call(API.projects);
    if (projects.status === 401) return await unauthorized();
    if (projects.status !== 200) return;
    const groups = [];
    for (const project of projects.body.body.projects) {
      const r = await call(route(API.sessions, project.id));
      if (r.status === 200) groups.push({ project, sessions: r.body.body.sessions });
    }
    page.groups = arrange(groups);
    page.marker = marker;
    page.applied = { epoch: waiting.body.epoch, revision: waiting.body.revision };
    if (page.open) await readSession();
    else drawList();
  } catch {
    // A dropped network: the next poll tries again.
  } finally {
    page.refreshing = false;
  }
}

function drawList() {
  const nodes = [];
  const now = Date.now();
  for (const group of page.groups) {
    if (group.sessions.length === 0) continue;
    nodes.push(el('h2', group.project.name));
    for (const s of group.sessions) {
      const row = el('button', null, s.waiting ? 'row waiting' : 'row');
      if (s.waiting) {
        const reason = s.waiting_reason ? `: ${s.waiting_reason}` : '';
        row.append(el('span', `Waiting on you${reason}`, 'flag'));
      }
      row.append(el('strong', s.name));
      row.append(el('span', `${s.kind} · ${s.card} · ${ago(s.last_activity_ms, now)}`, 'meta'));
      row.addEventListener('click', () => openSession(s));
      nodes.push(row);
    }
  }
  if (nodes.length === 0) nodes.push(el('p', 'No sessions.', 'note'));
  show(...nodes);
}

function findSession(id) {
  for (const group of page.groups) {
    const s = group.sessions.find((x) => x.id === id);
    if (s) return s;
  }
  return null;
}

async function openSession(s) {
  page.open = s.id;
  await readSession();
}

async function readSession() {
  const s = findSession(page.open);
  if (!s) {
    page.open = null;
    drawList();
    return;
  }
  const path = s.kind === 'claude' ? API.lastResponse : API.screen;
  const r = await call(route(path, s.id));
  if (r.status === 401) return unauthorized();
  if (r.status !== 200) return drawSession(s, 'Nothing to show.');
  // A content key has its own revision, so a reply is judged against
  // the last one read for that session, not the list's.
  if (!isCurrent(page.contentApplied[s.id], r.body)) return;
  page.contentApplied[s.id] = { epoch: r.body.epoch, revision: r.body.revision };
  drawSession(s, r.body.body.text);
}

function drawSession(s, text) {
  const back = el('button', 'Back');
  back.addEventListener('click', () => {
    page.open = null;
    drawList();
  });
  const nodes = [back, el('h2', s.name), el('p', `${s.kind} · ${s.card}`, 'note')];
  if (s.waiting) nodes.push(el('p', `Waiting on you: ${s.waiting_reason || ''}`, 'error'));
  nodes.push(el('pre', text));
  if (page.me.scope === 'control') {
    nodes.push(...replyBox(s));
  }
  // Keep an unsent draft across a redraw.
  const draft = document.getElementById('reply');
  const typed = draft ? draft.value : '';
  show(...nodes);
  const box = document.getElementById('reply');
  if (box && typed) box.value = typed;
}

function replyBox(s) {
  if (s.prompt_refusal) return [el('p', s.prompt_refusal, 'note')];
  const box = el('textarea');
  box.id = 'reply';
  box.setAttribute('aria-label', 'Reply');
  const status = el('p', '', 'note');
  const send = el('button', 'Send', 'primary');
  send.addEventListener('click', () => sendReply(s, box, status));
  return [box, send, status];
}

async function sendReply(s, box, status) {
  const text = box.value.trim();
  if (!text) return;
  // The same text reuses its op, so a retry after a dropped reply is
  // answered from the host's log rather than typed twice.
  let pending = page.pending[s.id];
  if (!pending || pending.text !== text) {
    pending = { op: randomHex(12), text };
    page.pending[s.id] = pending;
  }
  status.textContent = 'Sending…';
  try {
    const r = await call(route(API.send, s.id), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ op: pending.op, text }),
    });
    if (r.status === 200) {
      delete page.pending[s.id];
      box.value = '';
      status.textContent = 'Sent. The session’s card shows progress.';
    } else if (r.status === 401) {
      await unauthorized();
    } else if (r.status === 403 && r.body.error.code === 'scope') {
      const me = await call(API.me);
      if (me.status === 200) page.me = me.body.body;
      status.textContent = 'This device can only read.';
      await readSession();
    } else {
      status.textContent = (r.body && r.body.error && r.body.error.message) || 'Not sent.';
    }
  } catch {
    status.textContent = 'No answer. Send again to retry.';
  }
}

// --- staying current

async function tick() {
  if (document.hidden) return;
  try {
    const r = await call(API.waiting);
    if (r.status === 401) return await unauthorized();
    if (r.status !== 200) return;
    if (`${r.body.epoch}:${r.body.revision}` !== page.marker) await refresh();
  } catch {
    // The host is not answering; keep trying.
  }
}

function startPolling(ms) {
  page.pollMs = ms;
  clearInterval(page.pollTimer);
  page.pollTimer = setInterval(tick, ms);
}

// The socket is an enhancement: a change arrives at once. Safari may
// never connect it over a certificate the user accepted, and polling
// carries on either way.
function connectSocket() {
  if (typeof WebSocket === 'undefined') return;
  const socket = new WebSocket(`wss://${location.host}${API.events}`);
  page.socket = socket;
  socket.onopen = () => {
    page.retryMs = RETRY_FIRST;
    startPolling(POLL_SLOW);
  };
  socket.onmessage = (event) => {
    let frame = null;
    try {
      frame = JSON.parse(event.data);
    } catch {
      return;
    }
    if (frame.type === 'changed' || frame.type === 'removed') refresh();
    if (frame.type === 'resync_required') lost();
  };
  socket.onerror = () => {};
  socket.onclose = () => lost();
}

function lost() {
  if (page.socket) {
    page.socket.onclose = null;
    page.socket.close();
    page.socket = null;
  }
  startPolling(POLL_FAST);
  refresh();
  clearTimeout(page.retryTimer);
  page.retryTimer = setTimeout(connectSocket, page.retryMs);
  page.retryMs = Math.min(page.retryMs * 2, RETRY_MAX);
}

if (typeof document !== 'undefined') {
  boot();
}

if (typeof module !== 'undefined') {
  module.exports = { API, parseFragment, deviceName, infer401, isCurrent, route, arrange, ago };
}

