/// The 101 that switches a connection to WebSocket. The request was
/// already read by `read_request`, so `tungstenite::accept` cannot be
/// used; the stream is wrapped with `from_raw_socket` after this.
fn respond_upgrade<W: Write>(w: &mut W, key: &str) -> io::Result<()> {
    write!(
        w,
        "HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: {}\r\n\r\n",
        tungstenite::handshake::derive_accept_key(key.as_bytes())
    )?;
    w.flush()
}

/// Write one JSON response. `no-store` and `nosniff` ride on every one:
/// a browser must not keep or reinterpret what a device read.
fn respond<W: Write>(
    w: &mut W,
    status: u16,
    headers: &[(&'static str, String)],
    body: &[u8],
) -> io::Result<()> {
    let mut all = vec![
        ("Cache-Control", "no-store".to_owned()),
        ("X-Content-Type-Options", "nosniff".to_owned()),
    ];
    all.extend(headers.iter().map(|(n, v)| (*n, v.clone())));
    write_response(w, status, "application/json", &all, "keep-alive", body)
}

/// Answer a page request: constant bytes, closed afterwards so the
/// connection frees its slot in the unauthenticated pool at once.
fn respond_page<W: Write>(w: &mut W, page: &web::Page) -> io::Result<()> {
    let headers: Vec<(&str, String)> = web::HEADERS
        .iter()
        .map(|(n, v)| (*n, (*v).to_owned()))
        .collect();
    write_response(
        w,
        200,
        page.content_type,
        &headers,
        "close",
        page.body.as_bytes(),
    )
}

/// Write one response. Head and body in one write, so a reply is one
/// TLS record and one segment.
fn write_response<W: Write>(
    w: &mut W,
    status: u16,
    content_type: &str,
    headers: &[(&str, String)],
    connection: &str,
    body: &[u8],
) -> io::Result<()> {
    let reason = match status {
        200 => "OK",
        400 => "Bad Request",
        401 => "Unauthorized",
        403 => "Forbidden",
        404 => "Not Found",
        405 => "Method Not Allowed",
        413 => "Content Too Large",
        429 => "Too Many Requests",
        503 => "Service Unavailable",
        504 => "Gateway Timeout",
        _ => "Error",
    };
    let mut head = format!(
        "HTTP/1.1 {status} {reason}\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\nConnection: {connection}\r\n",
        body.len()
    );
    for (name, value) in headers {
        let _ = write!(head, "{name}: {value}\r\n");
    }
    head.push_str("\r\n");
    let mut out = head.into_bytes();
    out.extend_from_slice(body);
    w.write_all(&out)?;
    w.flush()
}

